-- =============================================================================
-- Rollback: igualar produccion con desarrollo (2026-11-21)
-- Devuelve producción al estado previo: quita FKs y los indices nuevos, restaura
-- los indices simples que se eliminaron y el DEFAULT 'cliente' de rol_creador.
-- No toca datos. Idempotente.
-- =============================================================================
SET @db := DATABASE();

